INSERT INTO recipes (id, name, description, access_level, owner_id, last_updated_at)
VALUES
  -- User 1 (admin-user): 1 PUBLIC + 1 PRIVATE
  (1,  'Shakshuka', 'This vibrant and aromatic Middle Eastern dish features perfectly poached eggs nestled in a rich, spiced tomato and bell pepper sauce that has been simmered to perfection with a harmonious blend of cumin, paprika, and cayenne pepper. The dish originates from North Africa and has become a beloved breakfast and brunch staple across the Mediterranean region, with each culture adding its own unique twist to this versatile recipe. The key to exceptional shakshuka lies in the patience required to develop the deep, complex flavors in the tomato base - allowing the peppers to soften completely and the spices to bloom in the oil creates an incredibly aromatic foundation. Fresh cilantro, parsley, and crumbled feta cheese traditionally garnish this dish, adding brightness and tangy creaminess that perfectly complements the rich sauce. Served with crusty bread for dipping into the runny egg yolks and savory sauce, this communal dish brings people together around the table and has become increasingly popular in modern brunch culture worldwide.', 'PUBLIC', 1, NOW()),
  (2,  'Grandma''s Secret Meatballs', 'This cherished family recipe has been carefully guarded and lovingly passed down through four generations of home cooks, each adding their own subtle refinements while preserving the essential character that makes these meatballs truly special. The secret lies in a proprietary blend of spices that Grandma developed over decades of experimentation, combined with a specific ratio of three different ground meats that creates an incomparably tender and flavorful result. What sets these meatballs apart is not just the ingredients themselves, but the technique - the gentle handling of the meat mixture to maintain tenderness, the precise browning process that develops a rich crust while keeping the interior moist, and the slow simmering in a tomato sauce that has been enriched with red wine and aromatic vegetables. Family members who have tried to recreate this recipe without Grandma''s guidance often come close but inevitably miss that indefinable quality that makes her version legendary at every family gathering and holiday celebration. The recipe card, stained with decades of use and written in Grandma''s distinctive handwriting, remains one of the most treasured possessions in our family archives.', 'PRIVATE', 1, NOW()),

  -- User 2 (regular-user-1): 1 PUBLIC + 1 PRIVATE
  (3,  'Spaghetti Carbonara', 'This authentic Roman pasta dish represents the pinnacle of Italian cucina povera - humble peasant cooking that transforms a handful of simple ingredients into something transcendent through perfect technique and timing. True carbonara contains no cream despite what many restaurants might serve - the silky, luxurious sauce comes from the magical emulsion of starchy pasta water, raw eggs, aged Pecorino Romano cheese, and rendered pork fat from guanciale or pancetta. The dish requires precise timing and temperature control: the pasta must be hot enough to cook the eggs into a creamy sauce, but not so hot that they scramble into clumps. Generous amounts of freshly cracked black pepper add a spicy bite that cuts through the richness, while the salty, funky notes from the Pecorino provide umami depth. Originally created as a hearty meal for Italian charcoal workers (carbonari), this dish has become one of Rome''s four classic pasta preparations and a test of any cook''s understanding of Italian technique. When executed properly, each strand of spaghetti should be coated in a glossy, cream-colored sauce that clings beautifully, with flecks of black pepper throughout and crispy bits of pork adding textural contrast.', 'PUBLIC', 2, NOW()),
  (4, 'Mom''s Chocolate Cake', 'This is not just any chocolate cake - this is the cake that has been requested for every birthday, celebration, and special occasion in our family for as long as anyone can remember, achieving almost mythical status among those lucky enough to have tasted it. The layers are incredibly moist, staying tender for days due to a secret ingredient that Mom discovered by accident when she ran out of a traditional component and had to improvise with something unexpected from the pantry. The chocolate flavor is deep and complex, using a combination of high-quality Dutch-processed cocoa powder and melted dark chocolate, along with a touch of espresso powder that enhances the chocolate notes without making it taste like coffee. What truly sets this cake apart, however, is the frosting - a rich, fudgy buttercream that somehow manages to be both light and intensely chocolatey, with a texture that''s smooth as silk and spreads like a dream. The frosting recipe itself is a closely guarded secret, though family members have noted hints of something unexpected that gives it an addictive quality that keeps people coming back for slice after slice. Mom always says the key is to not overmix the batter and to let the layers cool completely before frosting, but even when we follow her instructions precisely, our versions never quite match the original magic she creates in her kitchen.', 'PRIVATE', 2, NOW()),

  -- User 3 (regular-user-2): 1 PUBLIC + 1 PRIVATE
  (5, 'Margherita Pizza', 'Named after Queen Margherita of Italy and featuring the three colors of the Italian flag, this iconic Neapolitan pizza represents the perfect marriage of simplicity and excellence, proving that with the finest ingredients and proper technique, less truly is more. The foundation begins with the dough - a simple mixture of "00" flour, water, salt, and yeast that undergoes a slow, cold fermentation for at least 24 hours, developing complex flavors and the characteristic chewy yet tender texture that defines great Neapolitan pizza. The sauce is barely cooked, preserving the bright, fresh flavor of San Marzano tomatoes, simply crushed by hand and seasoned with just sea salt and perhaps a touch of fresh basil. Fresh mozzarella di bufala, torn into pieces rather than shredded, provides creamy pockets of dairy richness that contrast beautifully with the acidic tomatoes. The pizza bakes in an extremely hot wood-fired oven - ideally around 900°F - for just 60-90 seconds, emerging with a leopard-spotted, blistered crust that''s simultaneously crispy and chewy, slightly charred in spots, and puffed around the edges into a tall, airy cornicione. Fresh basil leaves are added after baking, their aromatic oils released by the residual heat, and a final drizzle of excellent extra-virgin olive oil brings everything together. This pizza is the standard by which all other pizzas are judged, and in Naples, there are strict regulations about what can legitimately be called a pizza Margherita.', 'PUBLIC', 3, NOW()),
  (6, 'Nonna''s Pasta Sauce', 'This legendary marinara sauce has been the foundation of countless Sunday dinners and the source of endless requests from family friends who can never quite replicate its unique flavor despite being given "all" the ingredients. Nonna begins with San Marzano tomatoes imported from Italy, but the real secret lies in what happens next - a combination of preparation techniques, timing, and that indefinable something that comes from decades of experience and intuition. The sauce simmers for at least four hours, and during that time, Nonna performs a series of adjustments and additions that she claims to do by feel rather than measurement. There are whispers among family members about a secret ingredient that gets added near the end of cooking, something unexpected that creates a subtle sweetness and depth that goes beyond ordinary sugar or traditional seasonings. The aromatic base includes garlic, onions, and fresh herbs from her garden, but the proportions and the exact moment each element is added remain a mystery that Nonna guards jealously, insisting that "you have to feel it, not measure it." When family members attempt to watch her make the sauce, she somehow manages to distract them at crucial moments, or adds things when no one is looking. The resulting sauce is neither too thick nor too thin, with a vibrant red color and a flavor that''s simultaneously bright and deeply complex, coating pasta perfectly and making even the simplest dishes taste extraordinary.', 'PRIVATE', 3, NOW()),

  -- User 4 (regular-user-3): 1 PUBLIC + 1 PRIVATE
  (7, 'Thai Green Curry', 'This fragrant and complex Thai curry showcases the incredible depth of flavor that can be achieved when fresh aromatics, spices, and coconut milk are combined with skill and balance, creating a dish that is simultaneously creamy, spicy, herbal, and subtly sweet. The curry paste itself is traditionally made from scratch using a granite mortar and pestle, pounding together fresh green chilies, lemongrass, galangal, makrut lime leaves, coriander roots, cumin, white pepper, shrimp paste, and shallots into a smooth, intensely aromatic paste that forms the flavor foundation of the entire dish. The paste is then fried in coconut cream until the oils separate and the raw edge of the chilies mellows into a more rounded heat, releasing those incredible aromatics that will perfume your entire kitchen. Coconut milk is added gradually, along with vegetables like Thai eggplant, bamboo shoots, and Thai basil, each component adding its own textural and flavor element to the finished curry. The balance of flavors is crucial - fish sauce provides salty umami depth, palm sugar adds subtle sweetness to balance the heat and sour notes, and fresh lime juice at the end brightens everything up. Protein options can include chicken, shrimp, or tofu, but the curry itself is the star, with its distinctive green color coming from the fresh green chilies and herbs rather than any artificial coloring.', 'PUBLIC', 4, NOW()),
  (8, 'Uncle''s BBQ Sauce', 'This award-winning barbecue sauce took first place at three consecutive regional competitions and has been the subject of countless attempts at reverse engineering by competitors who simply cannot crack the code of what makes it so uniquely delicious and craveable. Uncle spent over a decade perfecting this recipe, starting with a traditional tomato-based formula and gradually introducing unexpected elements that transformed it into something entirely his own. The sauce has a complex flavor profile that hits every taste receptor - sweet, sour, salty, spicy, and umami all present in perfect harmony, with no single element overwhelming the others. There are hints of smoke, though Uncle swears he doesn''t use liquid smoke, and a subtle fruity undertone that people can detect but can''t quite identify. The consistency is ideal - thick enough to cling to meat without sliding off, but not so thick that it burns easily when exposed to high heat. Uncle keeps the complete recipe in a safe deposit box at the bank, with only partial ingredient lists shared with family members, and he always makes the final mixing himself, sending everyone out of the kitchen during the crucial final steps. Local restaurants have offered substantial sums to buy the recipe, but Uncle refuses all offers, saying this sauce represents his legacy and will only be passed down to someone who truly appreciates the art of barbecue. The sauce has developed such a following that Uncle now produces small batches for family and close friends, each jar numbered and considered a precious commodity.', 'PRIVATE', 4, NOW()),

  -- User 5 (regular-user-4): 1 PUBLIC + 1 PRIVATE
  (9, 'Quinoa Salad', 'This vibrant, healthful salad represents the perfect intersection of nutritious ingredients and bold Mediterranean flavors, proving that eating well doesn''t mean sacrificing taste or satisfaction. The foundation is properly cooked quinoa - fluffy, separate grains that have been toasted before cooking to enhance their natural nutty flavor, then cooked in vegetable broth rather than water for extra depth. Once cooled, the quinoa is tossed with an abundance of fresh vegetables: ripe cherry tomatoes bursting with sweetness, crisp cucumber that adds refreshing crunch, thinly sliced red onion that provides a sharp bite, and Kalamata olives that contribute briny, savory notes. Crumbled feta cheese, preferably from sheep''s milk, adds creamy tanginess and a pleasant saltiness that ties all the vegetables together. The dressing is a simple but perfect combination of fresh lemon juice, excellent extra-virgin olive oil, minced garlic, dried oregano, and fresh herbs like parsley and mint, creating a bright, acidic counterpoint to the hearty quinoa and rich feta. What makes this salad special is its ability to improve as it sits - the quinoa absorbs the dressing and the flavors meld together beautifully, making it an ideal make-ahead dish for meal prep or potlucks. It''s substantial enough to serve as a complete vegetarian meal, yet light and refreshing enough for hot summer days, and it provides a complete protein thanks to the quinoa''s amino acid profile.', 'PUBLIC', 5, NOW()),
  (10, 'Dad''s Chili Recipe', 'This legendary chili has won more cooking competitions than any other dish in our family''s repertoire, taking top honors at county fairs, church cook-offs, and even a regional championship that came with a trophy that still sits proudly displayed in Dad''s kitchen. What makes this chili a champion is something that Dad has never fully disclosed - there are ingredients he adds when no one is watching, a specific sequence of cooking steps that he performs with almost ritualistic precision, and techniques he''s developed over thirty years of refinement that he guards more carefully than any other secret. The chili has a deep, complex flavor that develops over hours of slow cooking, with layers of heat that build gradually rather than hitting you all at once, and an almost velvety texture that suggests the presence of some secret thickening agent or technique. Dad uses a proprietary blend of spices that he mixes himself and stores in an unmarked container, and family members who have tried to sneak a taste or identify the components have been thwarted by the complexity and the number of different spices involved. The meat is browned in batches to develop maximum flavor, the beans (when included, as Dad makes both versions depending on the competition rules) are cooked from dried rather than canned, and there are whispered rumors about a secret ingredient that might include coffee, chocolate, beer, or something even more unexpected. Every time someone thinks they''ve figured out the recipe, Dad makes it for them and they realize they''re still missing something crucial - that indefinable quality that transforms good chili into championship-caliber chili.', 'PRIVATE', 5, NOW()),

  -- User 6 (disabled-user-1): 1 PUBLIC + 1 PRIVATE
  (11, 'Lasagna Bolognese', 'This authentic Northern Italian lasagna represents the pinnacle of comfort food sophistication, featuring delicate sheets of fresh egg pasta layered with a slowly simmered Bolognese ragù that has developed incredible depth through hours of patient cooking, and a creamy béchamel sauce that adds luxurious richness to every bite. The Bolognese sauce is nothing like the quick meat sauces often served in Italian-American restaurants - instead, it''s a carefully constructed symphony of flavors that begins with a soffritto of finely diced onions, carrots, and celery, sautéed in butter until soft and sweet. Ground beef and pork are added and cooked until deeply browned, then the whole mixture is deglazed with white wine and combined with tomato paste, whole milk, and just enough tomato for color and acidity without overwhelming the meat. This mixture then simmers for a minimum of three hours, with some traditional recipes calling for up to six hours, during which time the milk tenderizes the meat and creates an incredibly silky texture, while the flavors meld into something far greater than the sum of their parts. The béchamel is made fresh, whisking hot milk into a butter and flour roux until it reaches the perfect nappé consistency. Fresh pasta sheets are briefly blanched, then the layers are carefully constructed - pasta, ragù, béchamel, Parmigiano-Reggiano, repeat - creating a stunning cross-section when cut that reveals the distinct layers. The finished lasagna is baked until bubbling hot and golden on top, then allowed to rest so the layers set properly before serving. Each forkful contains all the elements in perfect proportion, creating a dish that is simultaneously hearty and refined, rustic and elegant.', 'PUBLIC', 6, NOW()),
  (12, 'Family Curry Powder', 'This bespoke spice blend has been the secret weapon in our family''s cooking for three generations, passed down with strict instructions about proportions, sourcing of ingredients, and the specific toasting and grinding techniques that give it a flavor profile unlike any commercial curry powder available in stores. The blend contains at least fifteen different spices, each sourced from specific vendors who are trusted to provide the highest quality whole spices that are absolutely fresh and aromatic. The process of making the curry powder is almost ceremonial - whole spices are individually toasted in a dry pan just until their essential oils are released and their aromas fill the kitchen, but not so long that they become bitter. Each spice requires a different toasting time and temperature, so they must be done separately and then combined. Once toasted and cooled, they are ground in small batches using a dedicated spice grinder, with the grinding done in a specific sequence that somehow affects the final flavor. The resulting powder is a complex blend of warm, earthy, floral, and pungent notes that can transform any dish it touches. Unlike store-bought curry powders that can taste flat or one-dimensional, this blend has incredible depth and changes character depending on how it''s used - bloomed in oil versus added to liquids, used at the beginning of cooking versus stirred in at the end. Family members guard their small jars of this curry powder jealously, measuring it out carefully and using it only for special dishes where its complexity can truly shine. The exact proportions and the complete list of spices remain known only to a few family members, who gather once a year to make a large batch that is then distributed to the extended family, each jar labeled with the year it was made and treated as the precious commodity it truly is.', 'PRIVATE', 6, NOW())
;

SELECT setval('recipes_id_seq', (SELECT MAX(id) FROM recipes));
